    [Fact]
    public async Task ReversalCreatesExactInverseAndRejectsDuplicate()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection());
        var posting = LedgerTestSupport.CreateRepository(dataSource); var operations = new LedgerOperationsRepository(dataSource, new NpgsqlTransactionCoordinator(dataSource), posting, TimeProvider.System);
        var original = await posting.PostCustomerInvoiceAsync(LedgerTestSupport.Invoice($"REV-{Guid.NewGuid():N}"));
        var reversal = await operations.ReverseAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, original.JournalEntryId, new(new(2026, 2, 1), "تصحيح قيد الاختبار"), Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        Assert.False(reversal.AlreadyPosted); Assert.StartsWith("REV-", reversal.EntryNumber, StringComparison.Ordinal);
        await Assert.ThrowsAsync<LedgerDomainException>(() => operations.ReverseAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, original.JournalEntryId, new(new(2026, 2, 1), "تكرار"), Guid.CreateVersion7(), Guid.CreateVersion7(), default));
        await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant);
        await using var command = new NpgsqlCommand("select coalesce(sum(case when journal_entry_id=$2 then base_debit-base_credit else 0 end),0)+coalesce(sum(case when journal_entry_id=$3 then base_debit-base_credit else 0 end),0), count(*) from finance_ledger.journal_entry_line where tenant_id=$1 and journal_entry_id=any($4)", connection); command.Parameters.AddWithValue(LedgerTestSupport.AtlasTenant.Value); command.Parameters.AddWithValue(original.JournalEntryId); command.Parameters.AddWithValue(reversal.JournalEntryId); command.Parameters.AddWithValue(new[] { original.JournalEntryId, reversal.JournalEntryId }); await using var reader = await command.ExecuteReaderAsync(); Assert.True(await reader.ReadAsync()); Assert.Equal(0m, reader.GetDecimal(0)); Assert.Equal(6L, reader.GetInt64(1));
    }

