        var preparer = Guid.CreateVersion7(); var approver = Guid.CreateVersion7(); var poster = Guid.CreateVersion7(); var draft = await operations.CreateGeneralJournalDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(journal, new(2026, 3, 1), "قيد مصروف يدوي", "EGP", $"manual-{Guid.NewGuid():N}", [new(cash, 100m, 0m, "EGP", 100m, 0m, 100m, 0m), new(revenue, 0m, 100m, "EGP", 0m, 100m, 0m, 100m)]), preparer, default);
        await operations.SubmitGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, preparer, Guid.CreateVersion7(), default); await operations.ApproveGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, approver, Guid.CreateVersion7(), default); var posted = await operations.PostGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, poster, Guid.CreateVersion7(), default); Assert.False(posted.AlreadyPosted);
        var balance = await operations.GetAccountBalanceAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, cash, new(2026, 3, 1), new(2026, 3, 31), default); Assert.Equal(100m, balance.Debit); Assert.Equal(0m, balance.Credit);
