        var preparer = Guid.CreateVersion7(); var approver = Guid.CreateVersion7(); var poster = Guid.CreateVersion7(); var draft = await operations.CreateGeneralJournalDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(journal, new(2026, 8, 1), "أبعاد دورة كاملة", "EGP", $"dimension-lifecycle-{Guid.NewGuid():N}", [new(cash, 100m, 0m, "EGP", 100m, 0m, 100m, 0m, 1m, [cairo], "cash"), new(revenue, 0m, 100m, "EGP", 0m, 100m, 0m, 100m, 1m, [alexandria], "revenue")]), preparer, default); Assert.Equal(cairo, Assert.Single(draft.Lines[0].DimensionValueIds!)); Assert.Equal(alexandria, Assert.Single(draft.Lines[1].DimensionValueIds!));
