        var submitted = await operations.SubmitGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, preparer, Guid.CreateVersion7(), default); Assert.Equal(GeneralJournalDraftStatus.Submitted, submitted.Status); var approved = await operations.ApproveGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, approver, Guid.CreateVersion7(), default); Assert.Equal(GeneralJournalDraftStatus.Approved, approved.Status); var posted = await operations.PostGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, poster, Guid.CreateVersion7(), default); Assert.False(posted.AlreadyPosted);
        await Assert.ThrowsAsync<LedgerDomainException>(() => operations.UpdateGeneralJournalDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, new(journal, new(2026, 8, 1), "محاولة تعديل بعد النشر", "EGP", $"dimension-lifecycle-posted-{Guid.NewGuid():N}", edited.Lines), preparer, default));
        var dimensions = await ScalarLongAsync(connection, "select count(*) from finance_ledger.journal_line_dimension where tenant_id=$1 and legal_entity_id=$2 and journal_entry_line_id in (select id from finance_ledger.journal_entry_line where tenant_id=$1 and legal_entity_id=$2 and journal_entry_id=$3)", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, posted.JournalEntryId); Assert.Equal(2, dimensions);
