        await Assert.ThrowsAsync<LedgerDomainException>(() => operations.PostGeneralJournalAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, poster, Guid.CreateVersion7(), default));
        var deltaTenant = new Shared.Primitives.Identifiers.TenantId(Guid.Parse("3f93b180-d6a9-3e50-9c92-6be0607e96eb")); await using var deltaConnection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(deltaConnection, deltaTenant); var deltaEntity = await ScalarGuidAsync(deltaConnection, "select id from platform.legal_entity where tenant_id=$1 order by id limit 1", deltaTenant.Value); var deltaDefinition = await operations.CreateDimensionDefinitionAsync(deltaTenant, new(deltaEntity), new($"DELTA-BRANCH-{Guid.NewGuid():N}", "فرع دلتا", "Delta branch"), Guid.CreateVersion7(), default); var deltaValue = await operations.CreateDimensionValueAsync(deltaTenant, new(deltaEntity), new(deltaDefinition, "DELTA", "دلتا", "Delta"), Guid.CreateVersion7(), default);
        var crossTenantRequest = new CreateGeneralJournalDraftRequest(journal, new(2026, 8, 1), "cross tenant", "EGP", $"cross-tenant-{Guid.NewGuid():N}", [new(cash, 100m, 0m, "EGP", 100m, 0m, 100m, 0m, 1m, [deltaValue], null), new(revenue, 0m, 100m, "EGP", 0m, 100m, 0m, 100m)]); await Assert.ThrowsAsync<LedgerDomainException>(() => operations.CreateGeneralJournalDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, crossTenantRequest, preparer, default));
        await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant); var secondaryEntity = await ScalarGuidAsync(connection, "select id from platform.legal_entity where tenant_id=$1 and id<>$2 order by id limit 1", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value); var secondaryDefinition = await operations.CreateDimensionDefinitionAsync(LedgerTestSupport.AtlasTenant, new(secondaryEntity), new($"SECONDARY-BRANCH-{Guid.NewGuid():N}", "فرع ثانوي", "Secondary branch"), Guid.CreateVersion7(), default); var secondaryValue = await operations.CreateDimensionValueAsync(LedgerTestSupport.AtlasTenant, new(secondaryEntity), new(secondaryDefinition, "SEC", "ثانوي", "Secondary"), Guid.CreateVersion7(), default); var crossEntityRequest = crossTenantRequest with { IdempotencyKey = $"cross-entity-{Guid.NewGuid():N}", Lines = [crossTenantRequest.Lines[0] with { DimensionValueIds = [secondaryValue] }, crossTenantRequest.Lines[1]] }; await Assert.ThrowsAsync<LedgerDomainException>(() => operations.CreateGeneralJournalDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, crossEntityRequest, preparer, default));
    }

