    [Fact]
    public async Task ForeignCurrencySnapshotDimensionsAndReportsRemainExplicit()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection()); var posting = LedgerTestSupport.CreateRepository(dataSource); var operations = new LedgerOperationsRepository(dataSource, new NpgsqlTransactionCoordinator(dataSource), posting, TimeProvider.System); await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, default); await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant); var journal = await ScalarGuidAsync(connection, "select id from finance_ledger.journal where tenant_id=$1 and legal_entity_id=$2 and code='GENERAL'", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value); var debitAccount = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"7{Guid.NewGuid():N}"[..10], "عملة", "Foreign currency", AccountType.Asset, "Current", null), default)).Id; var creditAccount = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"8{Guid.NewGuid():N}"[..10], "عملة دائنة", "Foreign credit", AccountType.Revenue, "Current", null), default)).Id;
        var dimensionCode = $"BRANCH_{Guid.NewGuid():N}"; var definition = await operations.CreateDimensionDefinitionAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(dimensionCode, "الفرع", "Branch"), Guid.CreateVersion7(), default); var value = await operations.CreateDimensionValueAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(definition, "MAIN", "الرئيسي", "Main"), Guid.CreateVersion7(), default); await operations.CreateDimensionPolicyAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(definition, "Account", debitAccount.ToString("D"), "Required"), Guid.CreateVersion7(), default);
        var lines = new[] { new LedgerPostingLinePayload(debitAccount, 0m, 0m, "USD", 100m, 0m, 300m, 0m, 3m, [new(dimensionCode, value, "MAIN")], "foreign debit", null), new LedgerPostingLinePayload(creditAccount, 0m, 0m, "USD", 0m, 100m, 0m, 300m, 3m, [new(dimensionCode, value, "MAIN")], "foreign credit", null) }; var payload = new ExplicitLedgerPostingPayload(journal, "Foreign currency test", "EGP", lines); var fact = new AccountingFactEnvelope<IAccountingFactPayload>(Guid.CreateVersion7(), LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, AccountingFactTypes.ManualGeneralJournalPosted, 1, "ledger-test", $"fx:{Guid.NewGuid():N}", $"fx:{Guid.NewGuid():N}", new(2026, 5, 1), new(2026, 5, 1), payload, Guid.CreateVersion7(), Guid.CreateVersion7()); var result = await posting.PostAsync(fact); Assert.False(result.AlreadyPosted);
        await using var verify = new NpgsqlCommand("select transaction_debit,transaction_credit,base_debit,base_credit,exchange_rate from finance_ledger.journal_entry_line where tenant_id=$1 and legal_entity_id=$2 and journal_entry_id=$3 order by sequence_no", connection); verify.Parameters.AddWithValue(LedgerTestSupport.AtlasTenant.Value); verify.Parameters.AddWithValue(LedgerTestSupport.AtlasEntity.Value); verify.Parameters.AddWithValue(result.JournalEntryId); await using var reader = await verify.ExecuteReaderAsync(); var firstRead = await reader.ReadAsync(); Assert.True(firstRead, $"No first journal line for {result.JournalEntryId}"); Assert.Equal(100m, reader.GetDecimal(0)); Assert.Equal(300m, reader.GetDecimal(2)); Assert.Equal(3m, reader.GetDecimal(4)); var secondRead = await reader.ReadAsync(); Assert.True(secondRead, $"No second journal line for {result.JournalEntryId}"); Assert.Equal(100m, reader.GetDecimal(1)); Assert.Equal(300m, reader.GetDecimal(3)); await reader.DisposeAsync(); var report = await operations.GetGeneralLedgerAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(2026, 5, 1), new(2026, 5, 31), null, null, 200, default, journalId: journal, sourceModule: "ledger-test", dimensionDefinitionId: definition, dimensionValueId: value); Assert.Contains(report.Items, item => item.EntryId == result.JournalEntryId); var explanation = await operations.ExplainEntryAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, result.JournalEntryId, default); Assert.Equal(AccountingFactTypes.ManualGeneralJournalPosted, explanation.FactType); Assert.Equal(2, explanation.Lines.Count); var healthy = await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, default); Assert.True(healthy.Healthy); await using var corrupt = new NpgsqlCommand("update finance_ledger.account_period_balance set period_debit=period_debit+1 where ctid=(select ctid from finance_ledger.account_period_balance where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 limit 1)", connection); corrupt.Parameters.AddWithValue(LedgerTestSupport.AtlasTenant.Value); corrupt.Parameters.AddWithValue(LedgerTestSupport.AtlasEntity.Value); corrupt.Parameters.AddWithValue(debitAccount); await corrupt.ExecuteNonQueryAsync(); var drift = await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, default); Assert.False(drift.Healthy); Assert.NotEmpty(drift.Differences); var rebuilt = await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, default); Assert.True(rebuilt.RowsRebuilt > 0); Assert.True(rebuilt.Reconciled);
    }

    [Fact]
    public async Task CoordinatorCommitsAuditLedgerAndOutboxAsOneBoundary()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection()); var coordinator = new NpgsqlTransactionCoordinator(dataSource); var posting = LedgerTestSupport.CreateRepository(dataSource); var tenant = LedgerTestSupport.AtlasTenant; var entity = LedgerTestSupport.AtlasEntity; var journal = await ReadGuidAsync(dataSource, tenant, "select id from finance_ledger.journal where tenant_id=$1 and legal_entity_id=$2 and code='GENERAL'"); var cash = await ReadGuidAsync(dataSource, tenant, "select id from finance_ledger.account where tenant_id=$1 and legal_entity_id=$2 and code='110200'"); var revenue = await ReadGuidAsync(dataSource, tenant, "select id from finance_ledger.account where tenant_id=$1 and legal_entity_id=$2 and code='410100'");
        var factId = Guid.CreateVersion7(); var payload = new ExplicitLedgerPostingPayload(journal, "POC", "EGP", [new(cash, 50m, 0m, "EGP", 50m, 0m, 50m, 0m, 1m, [], "source", null), new(revenue, 0m, 50m, "EGP", 0m, 50m, 0m, 50m, 1m, [], "source", null)]); var fact = new AccountingFactEnvelope<IAccountingFactPayload>(factId, tenant, entity, AccountingFactTypes.ManualGeneralJournalPosted, 1, "reference-producer", $"poc:{factId:N}", $"poc:{factId:N}", new(2026, 4, 1), new(2026, 4, 1), payload, Guid.CreateVersion7(), Guid.CreateVersion7());
        var capability = new LedgerTransactionCapability(posting); var result = await coordinator.ExecuteAsync(tenant, async (context, ct) => { await using var source = new NpgsqlCommand("insert into platform.audit_entry (id,tenant_id,legal_entity_id,actor_type,module,action,entity_type,entity_id,source,correlation_id,occurred_at) values ($1,$2,$3,'System','reference-producer','poc.success','source', $4,'test',$5,now())", context.Connection, context.Transaction); source.Parameters.AddWithValue(Guid.CreateVersion7()); source.Parameters.AddWithValue(tenant.Value); source.Parameters.AddWithValue(entity.Value); source.Parameters.AddWithValue(factId); source.Parameters.AddWithValue(fact.CorrelationId); await source.ExecuteNonQueryAsync(ct); var posted = await capability.PostExplicitAsync(context, fact, payload, ct); return posted; }, default); Assert.False(result.AlreadyPosted);
    }

    [Fact]
    public async Task CoordinatorOutboxFailureRollsBackSourceFactEntryAndLines()
    {
