        var factId = Guid.CreateVersion7(); var payload = new ExplicitLedgerPostingPayload(journal, "POC outbox failure", "EGP", [new(cash, 25m, 0m, "EGP", 25m, 0m, 25m, 0m, 1m, [], "source", null), new(revenue, 0m, 25m, "EGP", 0m, 25m, 0m, 25m, 1m, [], "source", null)]); var fact = new AccountingFactEnvelope<IAccountingFactPayload>(factId, tenant, entity, AccountingFactTypes.ManualGeneralJournalPosted, 1, "reference-producer", $"poc:failure:{factId:N}", $"poc:failure:{factId:N}", new(2026, 4, 1), new(2026, 4, 1), payload, Guid.CreateVersion7(), Guid.CreateVersion7()); var capability = new LedgerTransactionCapability(posting);
        await Assert.ThrowsAsync<PostgresException>(() => coordinator.ExecuteAsync(tenant, async (context, ct) => { await using var source = new NpgsqlCommand("insert into platform.audit_entry (id,tenant_id,legal_entity_id,actor_type,module,action,entity_type,entity_id,source,correlation_id,occurred_at) values ($1,$2,$3,'System','reference-producer','poc.outbox.failure','source',$4,'test',$5,now())", context.Connection, context.Transaction); source.Parameters.AddWithValue(Guid.CreateVersion7()); source.Parameters.AddWithValue(tenant.Value); source.Parameters.AddWithValue(entity.Value); source.Parameters.AddWithValue(factId); source.Parameters.AddWithValue(fact.CorrelationId); await source.ExecuteNonQueryAsync(ct); await capability.PostExplicitAsync(context, fact, payload, ct); context.AddOutbox(new OutboxMessage(Guid.CreateVersion7(), "InjectedFailure", "not-json", tenant, DateTimeOffset.UtcNow, fact.CorrelationId, factId, "test")); return true; }, default));
        await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, tenant); Assert.Equal(0, await LedgerTestSupport.ScalarLongAsync(connection, "select count(*) from finance_ledger.accounting_fact where tenant_id=$1 and id=$2", ("tenant", tenant.Value), ("id", factId))); Assert.Equal(0, await LedgerTestSupport.ScalarLongAsync(connection, "select count(*) from finance_ledger.journal_entry where tenant_id=$1 and fact_id=$2", ("tenant", tenant.Value), ("id", factId))); Assert.Equal(0, await LedgerTestSupport.ScalarLongAsync(connection, "select count(*) from platform.audit_entry where tenant_id=$1 and entity_id=$2 and action='poc.outbox.failure'", ("tenant", tenant.Value), ("id", factId)));
    }

    [Fact]
    public async Task ReversalRejectsClosedOriginalDateAndConcurrentDuplicate()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection()); var posting = LedgerTestSupport.CreateRepository(dataSource); await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant); var period = await ScalarGuidAsync(connection, "select id from finance_ledger.accounting_period where tenant_id=$1 and legal_entity_id=$2 and start_date='2026-06-01'", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value); await posting.SetPeriodStatusAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, period, PeriodStatus.Open, default); var original = await posting.PostCustomerInvoiceAsync(LedgerTestSupport.Invoice($"CLOSED-REV-{Guid.NewGuid():N}", new(2026, 6, 1))); await posting.SetPeriodStatusAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, period, PeriodStatus.Closed, default); await Assert.ThrowsAsync<LedgerDomainException>(() => posting.ReverseAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, original.JournalEntryId, new(2026, 6, 2), null, "closed period", Guid.CreateVersion7(), Guid.CreateVersion7()));
        var valid = await posting.ReverseAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, original.JournalEntryId, new(2026, 7, 1), null, "open period", Guid.CreateVersion7(), Guid.CreateVersion7(), default); Assert.False(valid.AlreadyPosted);
        var concurrentOriginal = await posting.PostCustomerInvoiceAsync(LedgerTestSupport.Invoice($"CONCURRENT-REV-{Guid.NewGuid():N}", new(2026, 7, 2))); async Task<LedgerPostingResult?> Reverse() { try { return await posting.ReverseAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, concurrentOriginal.JournalEntryId, new(2026, 7, 3), null, "concurrent", Guid.CreateVersion7(), Guid.CreateVersion7(), default); } catch (LedgerDomainException) { return null; } }
        var results = await Task.WhenAll(Reverse(), Reverse()); Assert.Single(results, x => x is not null); Assert.Single(results, x => x is null);
    }

    [Fact]
    public async Task EntryExplanationRetainsPerLineMappingEvidenceAfterVersionChangeAndArchive()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection());
        var posting = LedgerTestSupport.CreateRepository(dataSource);
        var operations = new LedgerOperationsRepository(dataSource, new NpgsqlTransactionCoordinator(dataSource), posting, TimeProvider.System);
        var lifecycle = new LedgerMappingConfigurationRepository(dataSource, new NpgsqlTransactionCoordinator(dataSource), new LedgerConfigurationCache(), TimeProvider.System);
        var v1Account = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"71{Guid.NewGuid():N}"[..10], "إيراد أول", "Revenue V1", AccountType.Revenue, "Sales", null), default)).Id;
        var v2Account = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"72{Guid.NewGuid():N}"[..10], "إيراد ثان", "Revenue V2", AccountType.Revenue, "Sales", null), default)).Id;
        await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant);
        var configurationA = await ScalarGuidAsync(connection, "select active_configuration_version_id from finance_ledger.ledger_entity_configuration where tenant_id=$1 and legal_entity_id=$2", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value);
        var originalRevenue = await ScalarGuidAsync(connection, "select v.target_account_id from finance_ledger.account_mapping_version v join finance_ledger.account_mapping m on m.tenant_id=v.tenant_id and m.legal_entity_id=v.legal_entity_id and m.id=v.mapping_id join finance_ledger.account_role r on r.tenant_id=m.tenant_id and r.legal_entity_id=m.legal_entity_id and r.id=m.role_id where v.tenant_id=$1 and v.legal_entity_id=$2 and v.accounting_configuration_version_id=$3 and r.code='SalesRevenue' and v.status='Active' order by v.version_number desc limit 1", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, configurationA);
        var entryA = await posting.PostCustomerInvoiceAsync(LedgerTestSupport.Invoice($"MAPPING-V1-{Guid.NewGuid():N}"));
        var draft = await lifecycle.CreateDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity,
            new(DateOnly.FromDateTime(DateTime.UtcNow)), Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        var revenueMapping = draft.Mappings.Single(mapping => mapping.RoleCode == "SalesRevenue");
        await lifecycle.UpdateDraftMappingAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id,
            revenueMapping.MappingVersionId, new(v2Account), Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        var validation = await lifecycle.ValidateAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        Assert.True(validation.Valid, System.Text.Json.JsonSerializer.Serialize(validation.Errors));
        await lifecycle.ActivateAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, draft.Id, Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        var entryB = await posting.PostCustomerInvoiceAsync(LedgerTestSupport.Invoice($"MAPPING-V2-{Guid.NewGuid():N}", new(2026, 2, 1)));
        var explanationA = await operations.ExplainEntryAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, entryA.JournalEntryId, default);
        var explanationB = await operations.ExplainEntryAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, entryB.JournalEntryId, default);
        var revenueA = Assert.Single(explanationA.Lines, line => line.AccountRole == "SalesRevenue"); var revenueB = Assert.Single(explanationB.Lines, line => line.AccountRole == "SalesRevenue");
        Assert.Equal(configurationA, explanationA.AccountingConfigurationVersionId); Assert.Equal(originalRevenue, revenueA.AccountId);
        Assert.Equal(draft.Id, explanationB.AccountingConfigurationVersionId); Assert.Equal(v2Account, revenueB.AccountId);
        var restoreDraft = await lifecycle.CreateDraftAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity,
            new(DateOnly.FromDateTime(DateTime.UtcNow)), Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        var restoreMapping = restoreDraft.Mappings.Single(mapping => mapping.RoleCode == "SalesRevenue");
        await lifecycle.UpdateDraftMappingAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, restoreDraft.Id,
            restoreMapping.MappingVersionId, new(originalRevenue), Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        Assert.True((await lifecycle.ValidateAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, restoreDraft.Id, Guid.CreateVersion7(), Guid.CreateVersion7(), default)).Valid);
        await lifecycle.ActivateAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, restoreDraft.Id, Guid.CreateVersion7(), Guid.CreateVersion7(), default);
        var immutableExplanation = await operations.ExplainEntryAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, entryA.JournalEntryId, default);
        Assert.Equal(configurationA, immutableExplanation.AccountingConfigurationVersionId);
        Assert.Equal(originalRevenue, Assert.Single(immutableExplanation.Lines, line => line.AccountRole == "SalesRevenue").AccountId);
        var deltaTenant = new Shared.Primitives.Identifiers.TenantId(Guid.Parse("3f93b180-d6a9-3e50-9c92-6be0607e96eb")); var deltaEntity = new Shared.Primitives.Identifiers.LegalEntityId(Guid.Parse("d8eb39bb-b048-7c5d-bacd-e3a923eee21c"));
        await Assert.ThrowsAsync<LedgerDomainException>(() => operations.ExplainEntryAsync(deltaTenant, deltaEntity, entryA.JournalEntryId, default));
        await Assert.ThrowsAsync<LedgerDomainException>(() => operations.ExplainEntryAsync(LedgerTestSupport.AtlasTenant, deltaEntity, entryA.JournalEntryId, default));
    }

    [Fact]
    public async Task ScopedReconciliationMeasuresFiscalPeriodsAndDetectsProjectionCorruptionMatrix()
    {
        await using var dataSource = NpgsqlDataSource.Create(LedgerTestSupport.RequireConnection()); var posting = LedgerTestSupport.CreateRepository(dataSource); var operations = new LedgerOperationsRepository(dataSource, new NpgsqlTransactionCoordinator(dataSource), posting, TimeProvider.System); await using var connection = await dataSource.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(connection, LedgerTestSupport.AtlasTenant);
        var journal = await ScalarGuidAsync(connection, "select id from finance_ledger.journal where tenant_id=$1 and legal_entity_id=$2 and code='GENERAL'", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value); var debitAccount = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"94{Guid.NewGuid():N}"[..10], "مصالحة مدين", "Reconciliation debit", AccountType.Asset, "Current", null), default)).Id; var creditAccount = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"95{Guid.NewGuid():N}"[..10], "مصالحة دائن", "Reconciliation credit", AccountType.Revenue, "Current", null), default)).Id; var extraAccount = (await posting.CreateAccountAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"96{Guid.NewGuid():N}"[..10], "إسقاط زائد", "Extra projection", AccountType.Asset, "Current", null), default)).Id;
        var baseYear = 2100 + BitConverter.ToUInt16(Guid.NewGuid().ToByteArray(), 0) % 7000;
        var yearA = await posting.CreateFiscalYearAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"FY-A-{Guid.NewGuid():N}", new(baseYear, 1, 1), new(baseYear, 12, 31)), default); var p1 = await posting.CreatePeriodAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(yearA.Id, "P1", new(baseYear, 1, 1), new(baseYear, 6, 30), 1), default); var p2 = await posting.CreatePeriodAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(yearA.Id, "P2", new(baseYear, 7, 1), new(baseYear, 12, 31), 2), default); var yearB = await posting.CreateFiscalYearAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new($"FY-B-{Guid.NewGuid():N}", new(baseYear + 1, 1, 1), new(baseYear + 1, 12, 31)), default); var p3 = await posting.CreatePeriodAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, new(yearB.Id, "P3", new(baseYear + 1, 1, 1), new(baseYear + 1, 12, 31), 1), default);
        async Task<LedgerPostingResult> PostAsync(DateOnly date, string reference) { var payload = new ExplicitLedgerPostingPayload(journal, reference, "EGP", [new(debitAccount, 100m, 0m, "EGP", 100m, 0m, 100m, 0m, 1m, [], reference, null), new(creditAccount, 0m, 100m, "EGP", 0m, 100m, 0m, 100m, 1m, [], reference, null)]); return await posting.PostAsync(new AccountingFactEnvelope<IAccountingFactPayload>(Guid.CreateVersion7(), LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, AccountingFactTypes.ManualGeneralJournalPosted, 1, "reconciliation-test", reference, reference, date, date, payload, Guid.CreateVersion7(), Guid.CreateVersion7())); }
        await PostAsync(new(baseYear, 2, 1), $"FY-A-P1-{Guid.NewGuid():N}"); await PostAsync(new(baseYear, 8, 1), $"FY-A-P2-{Guid.NewGuid():N}"); await PostAsync(new(baseYear + 1, 2, 1), $"FY-B-P3-{Guid.NewGuid():N}"); await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, default);
        Assert.True((await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, null, default)).Healthy); Assert.True((await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearB.Id, null, default)).Healthy); Assert.True((await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, p2.Id, default)).Healthy);
        var baselineP2 = await ScalarDecimalAsync(connection, "select closing_balance from finance_ledger.account_period_balance where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p2.Id);
        async Task RestoreAsync() { var rebuilt = await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, null, default); Assert.True(rebuilt.Reconciled); Assert.Equal(baselineP2, await ScalarDecimalAsync(connection, "select closing_balance from finance_ledger.account_period_balance where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p2.Id)); }
        async Task AssertMismatchAsync(string sql, params object[] values) { await ExecuteAsync(connection, sql, values); var mismatch = await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, p1.Id, default); Assert.False(mismatch.Healthy); Assert.NotEmpty(mismatch.Differences); foreach (var difference in mismatch.Differences) { Assert.Equal(p1.Id, difference.PeriodId); Assert.Equal(yearA.Id, difference.FiscalYearId); Assert.Equal(difference.CanonicalDebit - difference.ProjectionDebit, difference.DebitDifference); Assert.Equal(difference.CanonicalCredit - difference.ProjectionCredit, difference.CreditDifference); Assert.Equal(difference.CanonicalBalance - difference.ProjectionBalance, difference.BalanceDifference); } await RestoreAsync(); }
        await AssertMismatchAsync("update finance_ledger.account_period_balance set period_debit=period_debit+1 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p1.Id);
        await AssertMismatchAsync("update finance_ledger.account_period_balance set period_debit=period_debit-1 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p1.Id);
        await AssertMismatchAsync("update finance_ledger.account_period_balance set period_credit=period_credit+1 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, creditAccount, p1.Id);
        await AssertMismatchAsync("update finance_ledger.account_period_balance set period_credit=period_credit-1 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, creditAccount, p1.Id);
        await AssertMismatchAsync("update finance_ledger.account_period_balance set closing_balance=closing_balance+1 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p1.Id);
        await AssertMismatchAsync("delete from finance_ledger.account_period_balance where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p1.Id);
        await AssertMismatchAsync("insert into finance_ledger.account_period_balance (tenant_id,legal_entity_id,account_id,fiscal_year_id,accounting_period_id,dimension_key,currency_code,period_debit,closing_balance,updated_at) values ($1,$2,$3,$4,$5,'','EGP',1,1,now())", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, extraAccount, yearA.Id, p1.Id);
        await ExecuteAsync(connection, "insert into finance_ledger.account_period_balance (tenant_id,legal_entity_id,account_id,fiscal_year_id,accounting_period_id,dimension_key,currency_code,period_debit,closing_balance,updated_at) values ($1,$2,$3,$4,$5,'','EGP',1,1,now())", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, extraAccount, yearA.Id, p1.Id);
        await ExecuteAsync(connection, "update finance_ledger.account_period_balance set accounting_period_id=$5 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, extraAccount, p1.Id, p2.Id);
        var wrongPeriod = await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, null, default); Assert.False(wrongPeriod.Healthy); Assert.Contains(wrongPeriod.Differences, difference => difference.PeriodId == p2.Id); await RestoreAsync();
        await AssertMismatchAsync("update finance_ledger.account_period_balance set account_id=$5 where tenant_id=$1 and legal_entity_id=$2 and account_id=$3 and accounting_period_id=$4", LedgerTestSupport.AtlasTenant.Value, LedgerTestSupport.AtlasEntity.Value, debitAccount, p1.Id, extraAccount);
        var first = await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, null, default); var second = await operations.RebuildBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, null, default); Assert.Equal(first.RowsRebuilt, second.RowsRebuilt); Assert.True(second.Reconciled); Assert.True((await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearA.Id, p1.Id, default)).Healthy); Assert.True((await operations.ReconcileBalancesAsync(LedgerTestSupport.AtlasTenant, LedgerTestSupport.AtlasEntity, yearB.Id, p3.Id, default)).Healthy);
    }

    private static async Task<Guid> ScalarGuidAsync(NpgsqlConnection connection, string sql, params object[] values) { await using var command = new NpgsqlCommand(sql, connection); foreach (var value in values) command.Parameters.AddWithValue(value); return (Guid)(await command.ExecuteScalarAsync())!; }
    private static async Task<long> ScalarLongAsync(NpgsqlConnection connection, string sql, params object[] values) { await using var command = new NpgsqlCommand(sql, connection); foreach (var value in values) command.Parameters.AddWithValue(value); return Convert.ToInt64(await command.ExecuteScalarAsync(), System.Globalization.CultureInfo.InvariantCulture); }
    private static async Task<decimal> ScalarDecimalAsync(NpgsqlConnection connection, string sql, params object[] values) { await using var command = new NpgsqlCommand(sql, connection); foreach (var value in values) command.Parameters.AddWithValue(value); return Convert.ToDecimal(await command.ExecuteScalarAsync(), System.Globalization.CultureInfo.InvariantCulture); }
    private static async Task ExecuteAsync(NpgsqlConnection connection, string sql, params object[] values) { await using var command = new NpgsqlCommand(sql, connection); foreach (var value in values) command.Parameters.AddWithValue(value); await command.ExecuteNonQueryAsync(); }
    private static async Task<Guid> ReadGuidAsync(NpgsqlDataSource source, Shared.Primitives.Identifiers.TenantId tenant, string sql) { await using var c = await source.OpenConnectionAsync(); await LedgerTestSupport.SetTenantAsync(c, tenant); return await ScalarGuidAsync(c, sql, tenant.Value, LedgerTestSupport.AtlasEntity.Value); }
}
